*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#080a13;color:#f8f3ec;font-family:Manrope,Arial,sans-serif;overscroll-behavior:none}body{user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent}#game{position:relative;width:100%;height:100%;min-height:320px;overflow:hidden;background:radial-gradient(ellipse at 50% 70%,#322130 0,#111323 46%,#090b16 100%);isolation:isolate}#scene{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(6,8,16,.47),transparent 25%,transparent 55%,rgba(8,9,16,.3)),radial-gradient(ellipse at center,transparent 35%,rgba(4,5,11,.5) 100%);z-index:1}.topbar{position:absolute;top:0;left:0;right:0;height:86px;padding:20px 34px;display:flex;align-items:center;gap:12px;z-index:5;background:linear-gradient(180deg,rgba(8,10,18,.66),transparent)}.brand{display:flex;align-items:center;gap:11px;width:232px;font:600 16px Cinzel,serif;letter-spacing:3.3px}.brand-mark{color:#d39c88;font-size:26px;text-shadow:0 0 16px #b34d5a}.brand small{display:block;font:600 8px Manrope,sans-serif;letter-spacing:2.1px;color:#a6a4ad;margin-top:3px}.chapter{display:flex;align-items:center;gap:15px;margin-left:19px}.chapter-line{height:25px;width:1px;background:linear-gradient(transparent,#c59182,transparent)}.chapter small,.location small{display:block;color:#c5a99d;font-size:9px;letter-spacing:1.75px;font-weight:700}.chapter strong{display:block;font:500 14px Cinzel,serif;color:#f1e7df;margin-top:4px;letter-spacing:.25px}.icon-btn{width:37px;height:37px;margin-left:auto;border:1px solid rgba(229,199,177,.2);background:rgba(16,18,29,.46);color:#e1cfc2;border-radius:50%;font-size:20px;display:grid;place-items:center;cursor:pointer;transition:.2s}.icon-btn+.icon-btn{margin-left:0}.icon-btn:hover,.icon-btn.active{background:rgba(162,75,87,.3);border-color:#b98782;color:white}.map-btn{margin-left:auto}.location{position:absolute;top:111px;right:34px;display:flex;align-items:center;gap:11px;z-index:3;text-align:right}.location-pin{font-size:22px;color:#d4a396}.location small{font-size:8px;color:#b5aaa8;letter-spacing:2px}.location strong{display:block;font:500 15px Cinzel,serif;letter-spacing:.5px;margin-top:4px}.quest-card{position:absolute;z-index:3;top:124px;left:34px;width:264px;padding:17px 19px 15px;background:linear-gradient(120deg,rgba(13,15,26,.76),rgba(17,17,28,.44));border-left:1px solid rgba(203,147,129,.65);border-top:1px solid rgba(255,255,255,.07);backdrop-filter:blur(8px);box-shadow:0 14px 40px rgba(0,0,0,.13)}.quest-kicker{font-size:8px;letter-spacing:2.3px;color:#cc9d89;font-weight:800}.tiny-diamond{font-size:9px;margin-right:5px;color:#e3b39c}.quest-card h2{font:500 17px Cinzel,serif;letter-spacing:.2px;margin:9px 0 14px;color:#f6eee8}.quest-row{display:flex;align-items:center;gap:8px;height:27px;font-size:10px;color:#c4c0c5}.quest-row b{margin-left:auto;font-size:10px;color:#e4d4ca;font-weight:700}.quest-icon{width:16px;text-align:center;color:#c88782;font-size:14px}.quest-progress{height:2px;background:rgba(255,255,255,.1);margin:10px 0 9px}.quest-progress i{display:block;width:0;height:100%;background:#c77772;box-shadow:0 0 8px #c77772;transition:width .4s}.quest-note{font-size:9px;color:#938d9b;letter-spacing:.1px}.mini-map{position:absolute;z-index:3;top:162px;right:34px;width:144px;height:157px;padding:11px;background:rgba(12,14,24,.63);border:1px solid rgba(226,205,185,.18);box-shadow:0 8px 26px #090a1166;backdrop-filter:blur(5px);transition:opacity .2s,transform .2s}.mini-map.collapsed{opacity:0;transform:scale(.88);pointer-events:none}.map-title{font-size:7px;letter-spacing:1.5px;color:#d6c6bd;display:flex;justify-content:space-between}.map-title span{color:#d39588}.map-art{position:relative;margin:8px 0 7px;height:94px;overflow:hidden;background:radial-gradient(circle at 54% 46%,rgba(140,72,76,.28),transparent 51%),linear-gradient(135deg,#171a28,#202032);border:1px solid rgba(255,255,255,.08)}.map-forest{position:absolute;left:5px;top:5px;color:#5a645e;line-height:20px;font-size:17px;opacity:.65}.map-player,.map-gate,.map-enemy,.map-shard{position:absolute;display:block}.map-player{left:49%;top:51%;width:7px;height:7px;border-radius:50%;background:#e8c1aa;box-shadow:0 0 8px 3px #cf7772;z-index:2}.map-gate{right:7px;top:35%;width:8px;height:24px;border:1px solid #d59b83;border-radius:8px;box-shadow:0 0 8px #b75360}.map-enemy{width:5px;height:5px;background:#d36c70;border-radius:50%;box-shadow:0 0 5px #d36c70}.e1{left:28%;top:26%}.e2{left:69%;top:73%}.map-shard{font-style:normal;color:#e3c88f;font-size:8px;text-shadow:0 0 5px #e4c997}.s1{left:21%;top:65%}.s2{left:75%;top:20%}.s3{left:65%;top:51%}.map-legend{display:flex;justify-content:space-between;font-size:6px;letter-spacing:.6px;color:#b3abb0}.map-legend span{display:flex;align-items:center;gap:3px}.map-legend i{width:5px;height:5px;border-radius:50%;display:inline-block}.legend-you{background:#e8c1aa}.legend-enemy{background:#d36c70}.legend-shard{background:#e3c88f}.status-row{position:absolute;z-index:4;bottom:30px;left:34px;width:370px;display:flex;align-items:flex-end;gap:14px}.health-wrap,.blood-wrap{width:177px}.health-label,.blood-label{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;color:#e5d9d3;font-size:8px;letter-spacing:1.5px;font-weight:800}.health-label b,.blood-label b{letter-spacing:.3px;font-size:9px;color:#ede2dd}.heart{font-style:normal;color:#d58d86;font-size:12px;margin-right:4px}.bar{height:7px;padding:1px;background:rgba(10,11,18,.82);border:1px solid rgba(238,212,202,.29);position:relative;transform:skewX(-13deg);overflow:hidden}.bar i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#a84f5b,#dc8b83);box-shadow:0 0 9px #bd5860;transition:width .25s}.bar span{position:absolute;inset:0;background:linear-gradient(90deg,transparent 25%,rgba(255,255,255,.28) 25.5%,transparent 26%,transparent 58%,rgba(255,255,255,.2) 58.5%,transparent 59%)}.blood-wrap .bar i{background:linear-gradient(90deg,#7550a4,#c391dc);box-shadow:0 0 9px #9b64be}.level-badge{width:38px;height:38px;border:1px solid rgba(223,192,168,.62);transform:rotate(45deg);display:flex;flex-direction:column;justify-content:center;align-items:center;background:rgba(14,15,26,.75);margin:0 0 1px 5px;box-shadow:0 0 18px #3a203b}.level-badge span,.level-badge b{transform:rotate(-45deg);line-height:12px}.level-badge span{font-size:6px;letter-spacing:1px;color:#c5a795}.level-badge b{font:600 14px Cinzel,serif;color:#fff}.combat-hint{position:absolute;z-index:3;bottom:34px;left:50%;transform:translateX(-50%);display:flex;gap:8px;align-items:center;color:#c4bbc0;font-size:9px;letter-spacing:.2px;white-space:nowrap}.keycap{display:inline-grid;place-items:center;width:17px;height:17px;border:1px solid rgba(234,216,203,.35);background:rgba(12,13,22,.55);font-size:8px;color:#ead8cb}.combat-hint i{font-style:normal;color:#997f83;margin:0 2px}.touch-controls{display:none}.center-message{position:absolute;z-index:6;left:50%;top:38%;transform:translate(-50%,-50%);font:500 20px Cinzel,serif;letter-spacing:2px;color:#f4dfcf;text-shadow:0 2px 18px #d15c68;text-align:center;pointer-events:none;opacity:0;transition:opacity .4s}.center-message.show{opacity:1}.start-screen,.pause-screen{position:absolute;z-index:10;inset:0;display:grid;place-items:center;background:radial-gradient(ellipse at 50% 50%,rgba(13,14,25,.35),rgba(6,7,14,.77));transition:opacity .8s,visibility .8s}.start-screen.hidden,.pause-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-backdrop{position:absolute;inset:0;background:linear-gradient(90deg,rgba(7,8,15,.47),transparent 50%,rgba(7,8,15,.27))}.start-content{position:relative;text-align:center;margin-top:10px;animation:rise 1.1s ease both}.eyebrow{font-size:8px;letter-spacing:3.4px;color:#d0aa9b;font-weight:700;display:flex;align-items:center;justify-content:center;gap:12px}.eyebrow span{height:1px;width:25px;background:linear-gradient(90deg,transparent,#c69080)}.eyebrow span:last-child{transform:rotate(180deg)}.start-content h1{font:500 clamp(54px,9vw,100px)/1 Cinzel,serif;letter-spacing:.23em;text-indent:.23em;margin:19px 0 7px;color:#f1e6dc;text-shadow:0 4px 35px rgba(203,123,111,.28)}.subtitle{font:500 12px Manrope,sans-serif;letter-spacing:7px;color:#d29c8c;text-indent:7px}.title-ornament{color:#b97e78;font-size:12px;letter-spacing:4px;margin:20px 0}.start-content p{font:400 12px/1.9 Manrope,sans-serif;color:#c4bdc2;letter-spacing:.35px;margin:0 0 25px}.start-btn{position:relative;display:flex;align-items:center;justify-content:center;gap:20px;min-width:224px;height:47px;margin:0 auto;border:1px solid rgba(223,174,151,.74);background:linear-gradient(105deg,rgba(106,45,57,.8),rgba(80,46,63,.83));box-shadow:inset 0 0 20px rgba(212,137,123,.1),0 6px 25px rgba(0,0,0,.25);color:#f5e5db;cursor:pointer;font:700 9px Manrope,sans-serif;letter-spacing:2px;transition:all .22s}.start-btn:before{content:"";position:absolute;inset:4px;border:1px solid rgba(238,202,181,.18);pointer-events:none}.start-btn b{font-size:17px;font-weight:400;color:#e1b8a7;transition:transform .2s}.start-btn:hover{background:linear-gradient(105deg,#984754,#774362);box-shadow:0 0 28px rgba(195,83,98,.3)}.start-btn:hover b{transform:translateX(4px)}.start-foot{margin-top:21px;font-size:7px;letter-spacing:1.3px;color:#9e969f}.start-foot i{font-style:normal;margin:0 6px;color:#ce9287}.start-version{position:absolute;right:25px;bottom:18px;font-size:7px;letter-spacing:1.5px;color:#817e89}.start-version span{color:#c28d81;margin:0 5px}.pause-screen{background:rgba(7,8,15,.68);backdrop-filter:blur(7px)}.pause-card{text-align:center;padding:35px 48px;background:rgba(17,17,27,.91);border:1px solid rgba(213,168,145,.35);box-shadow:0 18px 70px #0008}.pause-card h2{font:500 42px Cinzel,serif;letter-spacing:7px;margin:15px 0 25px}.pause-tip{margin-top:18px;color:#a9a0a5;font-size:10px}.toast{position:absolute;z-index:8;top:80px;left:50%;transform:translate(-50%,-15px);padding:10px 18px;border:1px solid rgba(218,175,149,.4);background:rgba(13,14,24,.85);color:#e7d2c4;font-size:10px;letter-spacing:1px;opacity:0;transition:.35s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.fade{position:absolute;inset:0;z-index:9;background:#080911;opacity:0;pointer-events:none;transition:opacity .8s}.fade.active{opacity:1}.hidden{display:none!important}@keyframes rise{from{opacity:0;transform:translateY(15px)}to{opacity:1;transform:translateY(0)}}
