import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#scene');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x111320);scene.fog=new THREE.FogExp2(0x111320,.017);
const camera=new THREE.PerspectiveCamera(52,innerWidth/innerHeight,.1,180);
const clock=new THREE.Clock();
const hemi=new THREE.HemisphereLight(0xb7bdde,0x211c28,1.25);scene.add(hemi);
const moonLight=new THREE.DirectionalLight(0xc9d2f3,2.1);moonLight.position.set(-15,25,-14);moonLight.castShadow=true;moonLight.shadow.mapSize.set(1024,1024);moonLight.shadow.camera.left=-32;moonLight.shadow.camera.right=32;moonLight.shadow.camera.top=32;moonLight.shadow.camera.bottom=-32;scene.add(moonLight);
const crimson=new THREE.PointLight(0xe35469,18,35,2);crimson.position.set(7,8,-17);scene.add(crimson);
const ambientRed=new THREE.PointLight(0x943750,7,24,2);ambientRed.position.set(-10,3,7);scene.add(ambientRed);
const mat=(color,roughness=.8,metalness=0,emissive=0x000000,emissiveIntensity=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness,emissive,emissiveIntensity});
const groundMat=mat(0x282833,1);const rockMat=mat(0x3c3945,.95);const darkRock=mat(0x252631,1);const barkMat=mat(0x28242b,1);const leafMat=mat(0x202933,1);const redLeaf=mat(0x472a36,.9,0,0x240d19,.3);
const ground=new THREE.Mesh(new THREE.PlaneGeometry(120,120),groundMat);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
// Broken stone path, set dressing, and the distant moon.
const pathMat=mat(0x51454b,.95);for(let i=0;i<17;i++){const x=Math.sin(i*2.7)*1.5,z=13-i*2.05;const slab=new THREE.Mesh(new THREE.BoxGeometry(2.1+Math.sin(i)*.45,.12,1.4),pathMat);slab.position.set(x,-.015,z);slab.rotation.y=Math.sin(i*3)*.08;slab.rotation.x=.02;slab.receiveShadow=true;scene.add(slab)}
const moon=new THREE.Mesh(new THREE.SphereGeometry(3.2,32,24),new THREE.MeshBasicMaterial({color:0xc55268}));moon.position.set(10,18,-31);scene.add(moon);const moonGlow=new THREE.Mesh(new THREE.SphereGeometry(4.25,32,24),new THREE.MeshBasicMaterial({color:0x9d354f,transparent:true,opacity:.11,depthWrite:false}));moonGlow.position.copy(moon.position);scene.add(moonGlow);
const starGeo=new THREE.BufferGeometry(),starPos=[];for(let i=0;i<250;i++)starPos.push((Math.random()-.5)*95,Math.random()*32+4,-Math.random()*85-5);starGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPos,3));scene.add(new THREE.Points(starGeo,new THREE.PointsMaterial({color:0xe6d7d2,size:.095,transparent:true,opacity:.75})));
function addRock(x,z,s=1){const group=new THREE.Group();const a=new THREE.Mesh(new THREE.DodecahedronGeometry(1,0),Math.random()>.5?rockMat:darkRock);a.scale.set(s*(.7+Math.random()*.6),s*(.45+Math.random()*.6),s*(.7+Math.random()*.5));a.position.y=a.scale.y*.78;a.rotation.set(Math.random(),Math.random()*3,Math.random());a.castShadow=true;a.receiveShadow=true;group.add(a);group.position.set(x,0,z);scene.add(group);return group}
function addTree(x,z,size=1){const g=new THREE.Group();const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13*size,.25*size,3.8*size,7),barkMat);trunk.position.y=1.9*size;trunk.castShadow=true;g.add(trunk);for(let j=0;j<4;j++){const cone=new THREE.Mesh(new THREE.ConeGeometry((1.35-j*.2)*size,2.2*size,7),j===3?redLeaf:leafMat);cone.position.set((Math.random()-.5)*.4*size,(3.2+j*.72)*size,(Math.random()-.5)*.4*size);cone.rotation.z=(Math.random()-.5)*.12;cone.castShadow=true;g.add(cone)}g.position.set(x,0,z);scene.add(g);return g}
for(let i=0;i<28;i++){const side=i%2?1:-1,z=14-Math.random()*49,x=side*(7+Math.random()*13);addTree(x,z,.75+Math.random()*.9);if(Math.random()>.25)addRock(x-side*(1+Math.random()*2),z+Math.random()*3,.45+Math.random()*.9)}
for(let i=0;i<22;i++)addRock((Math.random()-.5)*42,10-Math.random()*45,.3+Math.random()*.75);
// Chapel ruins and a sealed arch at the end of the forest path.
const chapel=new THREE.Group();chapel.position.set(0,0,-24);scene.add(chapel);
